/**
 * @file dijkstra_demo.js
 * @brief Interactive Step-by-Step Dijkstra Algorithm Demonstrator
 *
 * Visualizes the inner workings of Dijkstra's algorithm using actual execution
 * step traces generated by the C backend engine.
 */

class DijkstraDemonstrator {
  constructor(containerId) {
    this.container = document.getElementById(containerId);
    this.traces = [];
    this.locations = [];
    this.currentIndex = 0;
    this.isPlaying = false;
    this.timer = null;
  }

  loadTraces(traces, locations, sourceId, destId) {
    this.traces = traces || [];
    this.locations = locations || [];
    this.sourceId = sourceId;
    this.destId = destId;
    this.currentIndex = 0;
    this.stopAutoPlay();
    this.render();
  }

  next() {
    if (this.currentIndex < this.traces.length - 1) {
      this.currentIndex++;
      this.render();
    } else {
      this.stopAutoPlay();
    }
  }

  prev() {
    if (this.currentIndex > 0) {
      this.currentIndex--;
      this.render();
    }
  }

  reset() {
    this.currentIndex = 0;
    this.stopAutoPlay();
    this.render();
  }

  toggleAutoPlay() {
    if (this.isPlaying) {
      this.stopAutoPlay();
    } else {
      this.startAutoPlay();
    }
  }

  startAutoPlay() {
    this.isPlaying = true;
    const playBtn = document.getElementById('demoPlayBtn');
    if (playBtn) playBtn.innerHTML = '⏸ Pause';
    this.timer = setInterval(() => {
      if (this.currentIndex < this.traces.length - 1) {
        this.next();
      } else {
        this.stopAutoPlay();
      }
    }, 1500);
  }

  stopAutoPlay() {
    this.isPlaying = false;
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    const playBtn = document.getElementById('demoPlayBtn');
    if (playBtn) playBtn.innerHTML = '▶ Play';
  }

  render() {
    if (!this.container) return;

    if (!this.traces || this.traces.length === 0) {
      this.container.innerHTML = `
        <div style="text-align: center; padding: 2rem; color: var(--text-muted);">
          <p>No algorithmic trace loaded yet.</p>
          <p style="font-size: 0.85rem; margin-top: 0.5rem;">Run a shortest path search from the Find Route tab to inspect the step-by-step C execution logs.</p>
        </div>
      `;
      return;
    }

    const currentTrace = this.traces[this.currentIndex];
    const totalSteps = this.traces.length;

    // Build Step Details Card
    let statusBadge = currentTrace.relaxed
      ? '<span style="background:#ecfdf5; color:#065f46; padding: 3px 8px; border-radius: 9999px; font-weight: 600; font-size: 0.8rem;">Edge Relaxed (Shorter Path Found)</span>'
      : '<span style="background:#f1f5f9; color:#475569; padding: 3px 8px; border-radius: 9999px; font-weight: 600; font-size: 0.8rem;">Checked / No Change</span>';

    this.container.innerHTML = `
      <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 1rem; flex-wrap: wrap; gap: 0.5rem;">
        <div>
          <span style="font-weight: 700; color: var(--primary-700); font-size: 1.05rem;">Step ${this.currentIndex + 1} of ${totalSteps}</span>
          <span style="margin-left: 0.5rem;">${statusBadge}</span>
        </div>
        <div style="display: flex; gap: 0.5rem;">
          <button id="demoPrevBtn" class="btn btn-secondary btn-sm" ${this.currentIndex === 0 ? 'disabled' : ''}>← Previous</button>
          <button id="demoPlayBtn" class="btn btn-primary btn-sm">${this.isPlaying ? '⏸ Pause' : '▶ Play'}</button>
          <button id="demoNextBtn" class="btn btn-secondary btn-sm" ${this.currentIndex === totalSteps - 1 ? 'disabled' : ''}>Next →</button>
          <button id="demoResetBtn" class="btn btn-secondary btn-sm">↺ Reset</button>
        </div>
      </div>

      <div style="background: var(--bg-card); border: 1px solid var(--border-color); border-radius: var(--radius-md); padding: 1.25rem; margin-bottom: 1rem; box-shadow: var(--shadow-xs);">
        <div style="font-weight: 600; color: var(--text-main); margin-bottom: 0.5rem;">
          Log Trace from C Core:
        </div>
        <div style="font-family: var(--font-mono); font-size: 0.9rem; color: var(--primary-800); background: var(--primary-50); padding: 0.85rem; border-radius: var(--radius-sm); border: 1px solid var(--primary-200);">
          ${currentTrace.desc}
        </div>
      </div>

      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 1rem; margin-bottom: 1rem;">
        <div style="background: var(--bg-subtle); padding: 1rem; border-radius: var(--radius-md); border: 1px solid var(--border-color);">
          <div style="font-size: 0.75rem; color: var(--text-muted); text-transform: uppercase; font-weight: 600;">Current Node Extracted</div>
          <div style="font-size: 1.15rem; font-weight: 700; color: var(--text-main); margin-top: 4px;">
            ${currentTrace.cur_id > 0 ? `Location #${currentTrace.cur_id}` : 'N/A'}
          </div>
        </div>

        <div style="background: var(--bg-subtle); padding: 1rem; border-radius: var(--radius-md); border: 1px solid var(--border-color);">
          <div style="font-size: 0.75rem; color: var(--text-muted); text-transform: uppercase; font-weight: 600;">Neighbor Evaluated</div>
          <div style="font-size: 1.15rem; font-weight: 700; color: var(--text-main); margin-top: 4px;">
            ${currentTrace.nbr_id > 0 ? `Location #${currentTrace.nbr_id}` : 'None (Self Settle)'}
          </div>
        </div>

        <div style="background: var(--bg-subtle); padding: 1rem; border-radius: var(--radius-md); border: 1px solid var(--border-color);">
          <div style="font-size: 0.75rem; color: var(--text-muted); text-transform: uppercase; font-weight: 600;">Distance Update</div>
          <div style="font-size: 1.15rem; font-weight: 700; color: var(--primary-700); margin-top: 4px;">
            ${currentTrace.relaxed ? `${currentTrace.old_dist >= 1e14 ? 'INF' : currentTrace.old_dist.toFixed(1)} → ${currentTrace.new_dist.toFixed(1)} km` : `${currentTrace.new_dist.toFixed(1)} km (Unchanged)`}
          </div>
        </div>
      </div>
    `;

    // Wire buttons
    const prevBtn = document.getElementById('demoPrevBtn');
    const playBtn = document.getElementById('demoPlayBtn');
    const nextBtn = document.getElementById('demoNextBtn');
    const resetBtn = document.getElementById('demoResetBtn');

    if (prevBtn) prevBtn.onclick = () => this.prev();
    if (playBtn) playBtn.onclick = () => this.toggleAutoPlay();
    if (nextBtn) nextBtn.onclick = () => this.next();
    if (resetBtn) resetBtn.onclick = () => this.reset();
  }
}
